"""Editorial catalogue. Each tool describes its actual output, assumptions and a worked example."""
GROUPS = {
 'files': ('File desk', 'Prepare files for delivery', 'Extract a sampler, package a bundle or check the file your buyer received.', '/sell-pdfs-on-shopify'),
 'images': ('Image studio', 'Create product visuals', 'Make a cover, size a listing image or prepare a printable at the right resolution.', '/sell-digital-art-on-shopify'),
 'catalog': ('Shop planner', 'Price and organise products', 'Work out the numbers and give every edition, bundle and key its own identity.', '/sell-license-keys-on-shopify'),
 'launch': ('Launch desk', 'Write listings and deliver orders', 'Give buyers a useful product page, a clear email and a link that takes them to the right place.', '/sell-canva-templates-on-shopify'),
}
TOOLS = {}
def add(key, group, slug, name, short, about, action, result, sample, steps, insight, example, faq, related, guide):
    TOOLS[key] = dict(key=key, group=group, slug=slug, name=name, short=short, about=about, action=action, result=result, sample=sample, steps=steps, insight=insight, example=example, faq=faq, related=related.split(), guide=guide)
add('extract','files','pdf-page-extractor','PDF page extractor','Extract PDF pages',
 'Choose pages from an ebook or workbook and save them as a separate PDF. Keep the order you enter to build a sample chapter or a custom handout.',
 'Extract pages','Sample PDF','workbook-sample.pdf',
 ['Choose an unlocked PDF, or try the four-page sample workbook.', 'Enter page positions such as 1, 3-4. Count the cover as page 1.', 'Extract the pages and open the new PDF to check the reading order.'],
 'Choose the first exercise that delivers a useful result on its own. If it refers to a diagram later in the book, include that page too. The extractor follows physical page positions, even when printed page labels use Roman numerals.',
 'For a four-page workbook, entering 1, 3-4 makes a three-page PDF. Entering 4, 1 instead puts the last page before the cover.',
 [('Can I change the order of extracted pages?', 'Yes. Enter 4, 1-2 to get pages four, one and two in that order. Repeated page positions are included once.'),('Does extracting a sampler change my full ebook?', 'No. You download a separate file. Your original stays on your device and the sample is not published to Shopify.'),('Will bookmarks, signatures and attachments carry over?', 'The tool copies pages into a new document. Do not rely on document-level bookmarks, forms, attachments or digital signatures surviving. Password-protected PDFs are not supported.')],
 'number zip', '/sell-ebooks-on-shopify')
add('number','files','add-page-numbers-to-pdf','PDF page numberer','Number PDF pages',
 'Add page numbers to a PDF workbook, ebook or printable. Choose the starting number and footer position, then download a numbered copy.',
 'Number my PDF','Numbered PDF','workbook-numbered.pdf',
 ['Open your PDF and pick a starting number.', 'Choose a footer position and select the number format.', 'Save the numbered copy and check the footers before delivery.'],
 'If the cover should stay unnumbered, extract the interior pages first, number them and merge the cover back on. A running number is printed on the page itself, so it also appears when customers print the file.',
 'A four-page handout starting at 7 receives the labels 7, 8, 9 and 10. With the plain number format, these are the only characters added.',
 [('Can I continue numbering from an earlier volume?', 'Yes. Enter the first number for this volume. Each following page increases by one.'),('Does this replace existing page numbers?', 'No. It draws new labels over the pages. Use a clean source PDF or choose an empty footer position.'),('Will this update my table of contents?', 'No. The existing contents, page labels and links are not recalculated. Review references yourself before sending the file.')],
 'extract merge', '/sell-pdfs-on-shopify')
add('zip','files','digital-product-zip-maker','Digital product ZIP maker','Make a ZIP bundle',
 'Package a template, a readme and bonus files into one downloadable ZIP. Keep the original file bytes intact and give the bundle a buyer-friendly name.',
 'Create ZIP bundle','ZIP archive','creator-kit.zip',
 ['Choose the files that belong in one purchase.', 'Give the archive a name that describes the edition or collection.', 'Download the ZIP, unpack it once and check the contents before listing it.'],
 'A bundle is easier to use when the first file tells the buyer what to open next. Include a short readme alongside the templates. This ZIP uses the store method: it packages the files together without trying to shrink them.',
 'The sample bundles a welcome note, a release checklist and a colour palette CSV. The buyer receives one ZIP containing three independent files.',
 [('Does the ZIP reduce the size of my files?', 'No. It stores each file without compression. Expect a ZIP slightly larger than the sum of its contents because the archive also stores filenames and headers.'),('Can I include PDFs, images and spreadsheets together?', 'Yes. The bytes are packaged as supplied. Choose up to 40 files, totalling no more than 64 MiB.'),('What happens to folders and duplicate filenames?', 'The archive has one flat file list. Unsafe path characters are removed and duplicate names receive a numbered suffix, so one selection cannot overwrite another.')],
 'hash download', '/sell-digital-art-on-shopify')
add('hash','files','file-checksum-generator','SHA-256 file checksum generator','Check a file checksum',
 'Fingerprint a digital download with SHA-256. Compare it with a checksum from a trusted source to see whether the two files have exactly the same contents.',
 'Calculate checksum','SHA-256 manifest','release.sha256',
 ['Choose a file from the delivered package.', 'Optionally paste a 64-character SHA-256 checksum from the publisher.', 'Compare the result or download a checksum manifest for your release.'],
 'A filename can stay the same across several releases; a checksum describes the bytes. Publish the expected value through a trusted channel. A matching hash is useful for checking integrity but cannot establish who created the file.',
 'For a file containing just the three bytes abc, the digest starts ba7816bf and ends f20015ad. Adding a newline produces a different result.',
 [('Will renaming the file change its SHA-256?', 'No. A change to the filename alone does not change the bytes being hashed.'),('Is this a malware scanner or a digital signature?', 'Neither. It checks a fingerprint. It does not inspect the contents for malware or verify the identity of a publisher.'),('Is a zip file’s checksum the same as a file inside it?', 'No. The ZIP has its own bytes, metadata and headers. Compare the checksum for the exact item you downloaded.')],
 'zip extract', '/sell-software-on-shopify')
add('download','files','file-download-time-calculator','File download time calculator','Estimate download time',
 'Estimate how long a customer needs to download a file. Adjust the file size, connection speed and usable share of that speed to compare delivery scenarios.',
 'Estimate download time','Transfer estimate','2 min 40 sec',
 ['Enter the total file size and its decimal unit.', 'Set the buyer’s connection speed in megabits per second.', 'Choose the usable percentage to account for an imperfect connection.'],
 'Download duration in seconds equals file megabytes × 8 divided by effective megabits per second. Use measured throughput at 100% efficiency, or use the advertised line speed with a lower usable share. Applying both adjustments would count the same loss twice.',
 'A 1 GB file is 8,000 megabits. At 50 Mbps and 100% usable speed, the estimated transfer takes 160 seconds, or 2 minutes 40 seconds.',
 [('Is Mbps the same as MB/s?', 'No. Mbps measures megabits per second. There are eight bits in a byte, so 80 Mbps corresponds to 10 MB/s before overhead.'),('Does this measure my internet speed?', 'No. It uses the speed you enter. It does not transfer a test file or make a network speed measurement.'),('Why might a real download take longer?', 'Wi-Fi conditions, server throughput, congestion and pauses can change the rate. This estimate does not include waiting time before the first byte arrives.')],
 'bandwidth zip', '/sell-videos-on-shopify')
add('watermark','images','image-watermark-maker','Image watermark maker','Watermark an image',
 'Put a text watermark on a product preview or sample illustration. Choose its colour, position and opacity, then save a PNG at the original dimensions.',
 'Apply watermark','Watermarked PNG','studio-proof.png',
 ['Choose a JPEG, PNG or WebP preview.', 'Enter the credit line and choose a placement buyers can still see.', 'Check the watermarked preview, then download the PNG.'],
 'For a product listing, mark a preview copy and deliver the clean artwork after checkout. A corner credit is unobtrusive; a centre mark is more visible. Neither placement prevents someone from copying a picture.',
 'A 1,200 × 800 preview marked “Studio proof” at 45% opacity stays 1,200 × 800. Only the exported copy contains the watermark.',
 [('Can I change the visibility of the text?', 'Yes. Use the opacity control and switch between light and dark ink. Run the tool again to compare versions.'),('Will the original image be overwritten?', 'No. The output is a new PNG. Keep the clean master for the buyer and use the marked image for your listing.'),('Can this watermark a whole animated image?', 'No. The tool exports one still frame, not an animated WebP or a video.')],
 'webp resize', '/sell-digital-art-on-shopify')
add('webp','images','image-to-webp-converter','Image to WebP converter','Convert to WebP',
 'Convert a JPEG, PNG or WebP product image to a still WebP. Compare the actual file sizes at your chosen quality before downloading the result.',
 'Convert to WebP','WebP image','product-preview.webp',
 ['Select a product photo, cover or still illustration.', 'Choose a quality setting. Start around 80% for a photo and inspect small details.', 'Compare the original and exported sizes and keep the version that works for your store.'],
 'A smaller image can make a media-heavy product page easier to load. Quality is an encoder setting, not a promise about file size. Text-heavy diagrams and already optimised images may be smaller in their original format.',
 'Convert one cover at 80%, then try 60%. Compare both at the size your customer will actually see; the tool reports the actual byte difference each time.',
 [('Does WebP conversion change the image dimensions?', 'No. The width and height stay the same. Use the image resizer first if the source is much larger than the listing needs.'),('Why is my WebP larger?', 'Lossy encoding is not always the smallest option for simple graphics or an already compact source. The size comparison reports an increase as well as a saving.'),('Does it preserve transparency and animation?', 'Transparency is supported when the browser encoder supports it. The output is a still image; animation and original metadata are not preserved.')],
 'resize watermark', '/sell-digital-art-on-shopify')
add('resize','images','shopify-product-image-resizer','Shopify product image resizer','Resize product images',
 'Fit a product image to an exact canvas size. Keep the whole image with padding or fill the frame with a centre crop, then download a ready-to-use PNG.',
 'Resize my image','Resized PNG','listing-1200x1200.png',
 ['Choose the source image and enter the target width and height.', 'Pick Fit for an uncropped image, or Fill to crop around the centre.', 'Review the preview and upload the finished PNG to your listing yourself.'],
 'Use the same canvas ratio across a collection to give your product grid a consistent rhythm. Fit is useful for covers with text at the edges. Fill is useful for photos that can lose a little background.',
 'A 1,200 × 800 landscape image fitted into a 1,200 × 1,200 square leaves 200 pixels above and below. Fill crops the sides instead.',
 [('Will the resizer stretch my image?', 'No. Both modes preserve the source aspect ratio. Fit adds padding; Fill trims the part outside the target canvas.'),('Which dimensions should I use for Shopify?', 'Choose the ratio and resolution that suit your theme and placement. The square preset is an editable example, not a Shopify requirement.'),('Will enlarging a small image add detail?', 'No. It creates more output pixels but cannot recover detail missing from the original. Inspect the preview before publishing.')],
 'webp dpi', '/sell-digital-art-on-shopify')
add('cover','images','ebook-cover-maker','Ebook cover maker','Design an ebook cover',
 'Design a typographic front cover for a digital guide. Choose an art direction, add your title and author credit, and export a 1,600 × 2,560 PNG.',
 'Render my cover','Cover artwork','field-notes-cover.png',
 ['Enter the title, subtitle and author exactly as they should appear.', 'Choose one of three original cover designs.', 'Render the cover and inspect both the full preview and its thumbnail.'],
 'Give the title the strongest visual weight. A subtitle that reads well at full size can disappear in a Shopify collection thumbnail. The output is a front cover; it does not add a spine, back cover or print bleed.',
 '“Field Notes” by North House pairs a short title with a small author line and a large abstract motif. Try the same words in the three designs before choosing.',
 [('Is this an AI image generator?', 'No. It typesets your text into original graphic layouts on your device. The same settings produce the same design.'),('Can I use the export as my actual ebook file?', 'The export is a PNG cover image. Add it to your ebook authoring software or use it as a listing visual; it is not the ebook itself.'),('What happens to long titles?', 'The title wraps and scales to the available space. If it cannot fit legibly, you will be asked to shorten it rather than receive a clipped cover.')],
 'resize webp', '/sell-ebooks-on-shopify')
add('dpi','images','printable-dpi-calculator','Printable DPI calculator','Check printable dimensions',
 'See how large a digital art file can print at a chosen pixel density. Enter its pixel dimensions and get the physical print size in inches and centimetres.',
 'Calculate print size','Print dimensions','12 × 18 in',
 ['Read the actual pixel dimensions of your artwork.', 'Enter the target pixels per inch for the intended print.', 'Use the resulting dimensions when writing the printable’s size guide.'],
 'For a raster file, print width equals pixel width divided by pixels per inch. Printers use dots of ink, but this calculator works with the image pixels you supply. Changing a resolution label by itself does not create more detail.',
 'A 3,600 × 5,400 file printed at 300 pixels per inch measures 12 × 18 inches, or 30.48 × 45.72 cm, before cropping or bleed.',
 [('Does this change the DPI metadata of my file?', 'No. It calculates physical dimensions. It does not open, resample or rewrite your image.'),('Does the result include bleed or a frame border?', 'No. The result uses the entire pixel area. Deduct the bleed, mat or crop allowance requested by your printer.'),('Should every print be 300 PPI?', 'Use your printer’s specification for the intended material and viewing distance. The default of 300 is a planning example.')],
 'resize cover', '/sell-digital-art-on-shopify')
add('price','catalog','digital-product-pricing-calculator','Digital product pricing calculator','Set a product price',
 'Work backwards from a target contribution margin. Enter your per-sale costs and payment fees to find a price floor for a digital product.',
 'Find my price floor','Minimum selling price','$18.38',
 ['Add the cost that each extra sale creates, such as a royalty or fulfilment expense.', 'Enter your actual percentage fee, fixed fee and target margin.', 'Use the calculated floor as one input alongside customer demand and product value.'],
 'The minimum price is (variable cost + fixed payment fee) ÷ (1 − percentage fee − target margin). Percentages are shares of the selling price. The result is rounded up to the next cent so rounding does not put the margin below the target.',
 'With $6.50 in variable costs, a $0.30 fixed fee, a 3% payment fee and a 60% margin target, the floor is $18.38. A markup of 60% on cost would give a different answer.',
 [('Is this a markup or a margin calculator?', 'Margin. It divides the contribution left after the listed costs and fees by the selling price.'),('Does the example payment fee come from Shopify?', 'No. The defaults illustrate the calculation. Enter the rates from your own payment provider and plan.'),('Are taxes and fixed creation costs included?', 'No. Enter amounts on a consistent tax basis. To find how many sales recover a fixed creation budget, use the break-even calculator.')],
 'breakeven bundle','/sell-ebooks-on-shopify')
add('breakeven','catalog','digital-product-break-even-calculator','Digital product break-even calculator','Find break-even sales',
 'Find how many paid orders recover the cost of creating a digital product. Include per-sale expenses and payment fees before counting a sale towards your launch.',
 'Find break-even orders','Orders to break even','50 orders',
 ['Enter the one-off budget you want the launch to recover.', 'Add price, per-order costs and fees for one completed sale.', 'Read the contribution per order and the first whole order count that covers the budget.'],
 'A download can cost very little to deliver but still take weeks to produce. Put design, recording or editing costs in the launch budget. Put royalties paid on every order in variable costs so they do not disappear when sales increase.',
 'A $900 launch budget divided by $18 of contribution per order breaks even at 50 orders. Order 49 leaves $18 to recover.',
 [('Why are break-even sales rounded up?', 'A fraction of an order cannot pay the remaining bill. The result rounds up to the next whole completed sale.'),('What if a sale contributes nothing?', 'There is no finite positive sales count that can recover a positive budget. Change price, fees or costs and run the calculation again.'),('Can I use this for a monthly subscription?', 'Use one consistent period. For example, use a monthly fixed budget and the contribution of one paid subscription-month. This does not model churn.')],
 'price revenue','/sell-online-courses-on-shopify')
add('bundle','catalog','bundle-discount-calculator','Bundle discount calculator','Price a bundle',
 'Compare a bundle price with the standalone prices of its contents. See the buyer’s saving, effective discount and combined list value before publishing the offer.',
 'Compare bundle prices','Bundle saving','Save $15 · 25%',
 ['List one item and its standalone price on each line.', 'Enter the price you actually plan to charge for the bundle.', 'Check the cash saving and percentage against the items your customer receives.'],
 'Use current, comparable standalone prices in the same currency. The denominator is the total standalone value, not the bundle price. A bundle priced above that total is a premium, not a discount.',
 'A $24 ebook, $18 workbook and $18 template total $60. At a bundle price of $45, the saving is $15, or 25% of standalone value.',
 [('Can I compare more than two digital products?', 'Yes. Enter up to 50 items, each on a new line as Name | Price. Each line represents one included item.'),('What if the bundle costs more than its contents?', 'The tool labels the difference as a premium. It does not turn a price increase into a claimed saving.'),('Does this create a discount in my store?', 'No. It compares the prices you enter. Set up the actual bundle or promotion in your store separately.')],
 'price sku','/features')
add('license','catalog','bulk-license-key-generator','Bulk license key generator','Generate license keys',
 'Generate grouped, readable alphanumeric keys for a software release. Add a product prefix and download a CSV you can register in your own licensing system.',
 'Generate license keys','Key inventory CSV','100 unique keys',
 ['Choose the number of keys, group count and characters per group.', 'Add an optional product prefix such as STUDIO.', 'Export the CSV, keep it private and register the keys in your fulfilment system.'],
 'A generated key is an identifier, not an activation service. Store a record of the batches you issue, validate on redemption and decide how to handle revocation. This tool deliberately does not keep a copy of your inventory.',
 'With the prefix STUDIO, three groups and four characters per group, the shape is STUDIO-XXXX-XXXX-XXXX. The actual characters are newly generated for each batch.',
 [('Are these keys random?', 'Yes. They use the browser’s cryptographic random source and an unambiguous alphanumeric alphabet. Duplicate keys are excluded within the generated batch.'),('Are keys guaranteed unique across separate exports?', 'No. The tool has no database of previous batches. Enforce a unique constraint or check your own inventory before importing new keys.'),('Do these activate software or Shopify discounts?', 'No. Your software or fulfilment system must recognise the values. The CSV is an inventory file, not a connected activation service.')],
 'sku hash','/sell-license-keys-on-shopify')
add('sku','catalog','digital-product-sku-generator','Product SKU generator','Build variant SKUs',
 'Build consistent SKU codes for combinations of digital product editions and formats. Preview the variant matrix and download a CSV inventory sheet.',
 'Build SKU matrix','Variant matrix CSV','6 variant SKUs',
 ['Choose a short product code such as NOTES.', 'List edition names and file formats, one value per line in each field.', 'Download one row per combination and check it against your existing catalogue.'],
 'Keep the readable option labels as well as the codes. A buyer sees “Studio edition” and “PDF”; an inventory system can use NOTES-STUDIO-EDITION-PDF. Consistent tokens make it easier to trace a fulfilment mistake back to a variant.',
 'Two editions, Standard and Deluxe, paired with PDF, EPUB and ZIP produce six rows. Each row keeps the edition, format and normalised SKU.',
 [('Does the CSV create Shopify variants automatically?', 'No. It is a three-column planning sheet. Map the SKUs to your store’s existing variants or import template separately.'),('How are accents, spaces and punctuation handled?', 'Codes use uppercase ASCII tokens, with spaces and punctuation turned into separators. Original display labels are kept in the CSV.'),('What if two names produce the same SKU?', 'The tool stops and identifies the collision. Rename one option rather than importing ambiguous identifiers.')],
 'license bundle','/sell-software-on-shopify')
add('snippet','launch','product-serp-preview','Product SERP preview','Preview a search snippet',
 'Preview how a product page title, URL and meta description could read in search. Edit the wording side by side, then copy or download the HTML title and meta tag.',
 'Preview my snippet','Search preview','Field Notes — Printable Workbook',
 ['Enter the public product URL and the title you want a buyer to see.', 'Describe what the buyer gets in one or two specific sentences.', 'Review the illustrative snippet, then copy the tags into the appropriate SEO fields.'],
 'A specific title is easier to evaluate than a string of repeated keywords. Name the product and its format, then use the description for a detail the title leaves out: the page count, intended buyer or task the product supports.',
 '“Field Notes — Printable Workbook” identifies the product and its format. A description can then tell the buyer that the download includes 24 guided prompts in a printable PDF.',
 [('Does this fetch or audit my existing Shopify page?', 'No. It previews what you enter. Paste your current title and description if you want to compare them.'),('Will Google display this exact snippet?', 'No. Search engines can choose different wording and truncate text depending on the query, device and layout. This is a writing preview.'),('What can I export?', 'A title element and a meta description tag with special HTML characters escaped. If your editor has plain-text SEO fields, paste the text itself instead of the tags.')],
 'faq utm','/sell-ebooks-on-shopify')
add('utm','launch','utm-link-builder','UTM campaign link builder','Build a campaign link',
 'Tag a public product URL for a newsletter, creator partnership or launch post. Keep existing product parameters and get a correctly encoded campaign link.',
 'Build campaign link','Tagged product link','Newsletter launch link',
 ['Start with the public URL customers should land on.', 'Enter source, medium and campaign. Use content or term only when useful.', 'Copy the final URL and open it once to check the destination before sharing it.'],
 'Choose a naming convention before the launch. For example, newsletter and Newsletter can become separate labels in reporting. The builder preserves the values you enter and replaces the standard UTM fields so a reused link does not acquire conflicting campaign tags.',
 'A summer newsletter can use source=newsletter, medium=email and campaign=field-notes. A variant parameter and an existing section anchor are preserved in the output URL.',
 [('Will this start tracking visitors on its own?', 'No. It adds parameters to a URL. Your site needs an analytics setup that reads them for a report to show campaign activity.'),('Does it remove a product variant or an anchor?', 'No. Unrelated query parameters and the fragment are preserved. The five standard UTM parameters are replaced by the new values.'),('Should I tag private customer download URLs?', 'Use a public landing page or product URL. Private fulfilment links can grant access to a purchase and should not be shared in a public campaign.')],
 'qr snippet','/features')
add('email','launch','digital-download-email-generator','Digital download email generator','Write a delivery email',
 'Write a clear delivery email with a product name, download link, opening instructions and support address. Copy the subject and message or save them as a text file.',
 'Create email draft','Delivery email','Your Field Notes download is ready',
 ['Enter the store and product names customers recognise from checkout.', 'Add an example download link and instructions specific to your file.', 'Review the draft and replace the sample link with buyer-specific delivery in your sending system.'],
 'A useful delivery email answers three questions immediately: what did I buy, where is it, and how do I open it? A ZIP buyer may need to extract the archive. A PDF buyer may only need a link and a reminder to save a personal copy.',
 'For a printable workbook, the draft includes a named download link, a note to print at actual size and a support address. Nothing is sent when you generate the preview.',
 [('Does the generator send an email?', 'No. It creates a plain-text draft locally. Send a test through your own email or fulfilment system before using it for orders.'),('Is the sample link protected?', 'This tool cannot protect a link. For real orders, insert the secure delivery link issued by your fulfilment app.'),('Can I use a Shopify or BIG template variable?', 'The link field accepts a sample web URL. After copying the draft, replace that example with the exact variable supported by your sending system.')],
 'canva faq','/features')
add('canva','launch','canva-template-delivery-pdf','Canva template delivery PDF maker','Make a Canva delivery PDF',
 'Turn a Canva template link into a branded one-page PDF with a clickable access button. Give Shopify customers a small, clear handout instead of a bare URL.',
 'Create delivery PDF','Clickable access PDF','template-access.pdf',
 ['Create the appropriate share link in Canva and test it as a buyer.', 'Enter the link, template title, shop name and a short set of instructions.', 'Download the access PDF and click its button in a PDF reader before uploading it to your product.'],
 'The PDF is a wrapper around a link. It does not duplicate the Canva design, change its permissions or stop someone forwarding it. Use a link intended for customer copies and test with an account that does not own the design.',
 'A social post template pack can be delivered as a one-page PDF titled “Your Studio Templates”, with one access button and a brief note about making the buyer’s own copy.',
 [('Does the tool turn an edit link into a template link?', 'No. It preserves the supplied destination. Obvious editor links are rejected, but only a real permission test can confirm what a buyer can access.'),('Where are my Canva design and link stored?', 'The tool writes the URL into a PDF in your browser. It does not connect to Canva, sign into your account or change the design.'),('Do buyers need an account or paid Canva elements?', 'That depends on the design and Canva’s access requirements. Check the experience with a separate account and disclose any paid elements in your listing.')],
 'email extract','/sell-canva-templates-on-shopify')
add('faq','launch','product-faq-builder','Product FAQ builder','Build a product FAQ',
 'Turn your own product questions and answers into an accessible accordion. Preview the questions, then export HTML with matching FAQPage JSON-LD.',
 'Build FAQ block','HTML + JSON-LD','product-faq.html',
 ['Write the questions customers ask before buying this specific download.', 'Add concise answers that match the files, compatibility and delivery you actually offer.', 'Preview the accordion, copy the HTML and check that your editor preserves the markup.'],
 'Start with concrete buying decisions: what files are included, which software opens them, and how a customer receives updates. A factual answer is useful even if no search engine shows a special search result.',
 'For a printable planner, “What paper size is included?” is more useful than “Is this product great?”. The same question and answer appear in both the visible HTML and the structured data.',
 [('Does this invent answers for my product?', 'No. You supply the facts. The tool formats them and keeps the visible content and machine-readable version in sync.'),('Can I use the accordion without JavaScript?', 'Yes. The exported accordion uses native HTML details and summary elements. The JSON-LD describes the same questions; it does not control the accordion.'),('Will FAQ markup guarantee rich results or AI citations?', 'No. Eligibility and display are decided by the search service. Check your theme for existing FAQ markup and avoid publishing two inconsistent versions.')],
 'snippet email','/faq')
